	"unsafe"
)

func main() {
	s := make([]int, 0, 4)
	s = append(s, 1)
	p := &s[0]
	for i := 2; i <= 5; i++ {
		s = append(s, i)
		fmt.Printf("len=%d cap=%d\n", len(s), cap(s))
	}
	*p = 99 // writes to the old array, not to s
	fmt.Println(s)
	fmt.Println(unsafe.Sizeof(s), unsafe.Sizeof([5]int{}))
}

