package main

import (
	"fmt"
	"unsafe"
)

func main() {
	names := make([]string, 0, 2)
	names = append(names, "Ana")
	first := &names[0]
	more := []string{"Ben", "Cy", "Dee"}
	for _, name := range more {
		names = append(names, name)
		fmt.Printf("len=%d cap=%d\n", len(names), cap(names))
	}
	*first = "Zed" // writes to the old array, not to names
	fmt.Println(names)
	fmt.Println(unsafe.Sizeof(names), unsafe.Sizeof("hello"))
}

