package main

import "fmt"

func zeroNegatives(s []int) {
	for i, v := range s {
		if v < 0 {
			s[i] = 0
		}
	}
}

func withBonus(s []int, x int) []int {
	return append(s, x)
}

func zeroNegativesArray(a [3]int) {
	for i, v := range a {
		if v < 0 {
			a[i] = 0 // changes only the function's copy
		}
	}
}

func main() {
	scores := []int{4, -2, 7, -5}
	zeroNegatives(scores)
	fmt.Println(scores)
	scores = withBonus(scores, 10)
	fmt.Println(scores)

	fixed := [3]int{-1, 6, -3}
	zeroNegativesArray(fixed)
	fmt.Println(fixed)
}
